typedef struct { void (*cb)(void *ctx, const message *); void *ctx; } sub_t;
static sub_t subs[MAX_SUBS]; static size_t nsubs; static pthread_mutex_t mtx = PTHREAD_MUTEX_INITIALIZER;

void channel_publish(const message *msg) {
    sub_t snap[MAX_SUBS]; size_t n;
    pthread_mutex_lock(&mtx);
    n = nsubs; memcpy(snap, subs, n * sizeof *snap);   /* snapshot */
    pthread_mutex_unlock(&mtx);
    for (size_t i = 0; i < n; i++)
        snap[i].cb(snap[i].ctx, msg);                  /* dispatch unlocked */
}
